const reverseString = (str) => {
  let reversed = "";
  for (let i = str.length - 1; i >= 0; i--) {
    reversed += str[i];
  };
  return reversed;
};

const anotherReverseString = (str) => {
  const charArray = str.split('');
  const reversedArray = charArray.reverse();
  const result = reversedArray.join('');
  return result;
};

const yetAnotherReverseString = (str) => {
  return str.split('').reverse().join('');
};

let testString1 = "hello";
let testString2 = "JavaScript";
let testString3 = "a";

console.log(reverseString(testString1));
console.log(anotherReverseString(testString2));
console.log(yetAnotherReverseString(testString3));
console.log(reverseString("world"));
console.log(anotherReverseString("openai"));

