function celsiusToFahrenheit(celsius) {
  const CONVERSION_FACTOR_MULT = 9 / 5;
  const CONVERSION_FACTOR_ADD = 32;

  let fahrenheit = celsius * CONVERSION_FACTOR_MULT;
  fahrenheit = fahrenheit + CONVERSION_FACTOR_ADD;

  return fahrenheit;
}

const temp1 = 0;
const result1 = celsiusToFahrenheit(temp1);
console.log(`0 Celsius is ${result1} Fahrenheit.`);

const temp2 = 25;
const result2 = celsiusToFahrenheit(temp2);
console.log(`25 Celsius is ${result2} Fahrenheit.`);

const temp3 = -10;
const result3 = celsiusToFahrenheit(temp3);
console.log(`-10 Celsius is ${result3} Fahrenheit.`);

