function calculateCircleArea(radius) {
  if (typeof radius !== 'number') {
    throw new Error("Radius must be a number.");
  }

  if (radius < 0) {
    throw new Error("Radius cannot be negative.");
  }

  let area = Math.PI * radius * radius;
  return area;
}

