  let result = 1;
  let i = 0;

  if (exponent === 0) {
    return 1;
  }

  if (exponent < 0) {
    base = 1 / base;
    exponent = -exponent;
  }

  while (i < exponent) {
    result *= base;
    i++;
  }

  return result;
};

