  const month = String(dateObj.getMonth() + 1).padStart(2, '0');
  const year = dateObj.getFullYear();
  const formattedDate = `${day}/${month}/${year}`;
  return formattedDate;
};

// Example usage and testing:
const date1 = new Date('2023-01-15');
const result1 = formatDateToDMY(date1);
console.log(result1); // Expected: 15/01/2023

const date2 = new Date('2024-12-01');
const result2 = formatDateToDMY(date2);
console.log(result2); // Expected: 01/12/2024

const date3 = new Date('1999-07-05T10:30:00Z');
const result3 = formatDateToDMY(date3);
console.log(result3); // Expected: 05/07/1999

const date4 = new Date();
const result4 = formatDateToDMY(date4);
console.log(result4); // Current date in DD/MM/YYYY format

