function updateInventory(inventory, item, quantity) {
  if (inventory.hasOwnProperty(item)) {
    inventory[item] += quantity;
  } else {
    inventory[item] = quantity;
  };
  return inventory;
};

// Example 1: Update existing item
let inventory1 = {apple: 10, orange: 5};
let updatedInventory1 = updateInventory(inventory1, 'apple', 5);
// expected: {apple: 15, orange: 5}

// Example 2: Add new item
let inventory2 = {apple: 10};
let updatedInventory2 = updateInventory(inventory2, 'banana', 3);
// expected: {apple: 10, banana: 3}

// Example 3: Update existing item with negative quantity
let inventory3 = {grape: 20, kiwi: 7};
let updatedInventory3 = updateInventory(inventory3, 'kiwi', -2);
// expected: {grape: 20, kiwi: 5}

// Example 4: Add new item with negative quantity (though typically quantities are positive)
let inventory4 = {};
let updatedInventory4 = updateInventory(inventory4, 'mango', -1);
// expected: {mango: -1}

// Example 5: Multiple updates
let inventory5 = {pen: 100};
updateInventory(inventory5, 'pen', 50);
updateInventory(inventory5, 'pencil', 20);
let finalInventory5 = updateInventory(inventory5, 'pen', -20);
// expected: {pen: 130, pencil: 20}

