function calculateMode(numbers) {
  if (!numbers || numbers.length === 0) {
    return [];
  }

  const counts = {};
  let maxCount = 0;

  for (let i = 0; i < numbers.length; i++) {
    const num = numbers[i];
    counts[num] = (counts[num] || 0) + 1;
    if (counts[num] > maxCount) {
      maxCount = counts[num];
    }
  }

  const modes = [];
  for (const numStr in counts) {
    if (counts[numStr] === maxCount) {
      modes.push(Number(numStr));
    }
  }

  return modes;
}

// Example usage:
const result1 = calculateMode([1, 2, 2, 3, 1]);
const result2 = calculateMode([1, 2, 3]);
const result3 = calculateMode([]);
const result4 = calculateMode([5, 5, 5, 2, 2]);
const result5 = calculateMode([1]);

