function isValidCreditCard(cardNumber) {
    let sum = 0;
    let isSecondDigit = false;

    for (let i = cardNumber.length - 1; i >= 0; i--) {
        let digit = parseInt(cardNumber[i], 10);

        if (isSecondDigit) {
            digit *= 2;
            if (digit > 9) {
                digit = digit - 9;
            }
        }
        sum += digit;
        isSecondDigit = !isSecondDigit;
    }
    return sum % 10 === 0;
};

