const decimalToBinary = (decimalNum) => {
  if (decimalNum === 0) {
    return "0";
  };

  let binaryString = "";
  let num = decimalNum;

  while (num > 0) {
    binaryString = (num % 2) + binaryString;
    num = Math.floor(num / 2);
  };

  return binaryString;
};

