class Queue {
  constructor() {
    this.elements = [];
    this.head = 0;
    this.tail = 0;
  }

  enqueue(element) {
    this.elements[this.tail] = element;
    this.tail++;
  }

  dequeue() {
    if (this.head === this.tail) {
      return null;
    }
    const item = this.elements[this.head];
    delete this.elements[this.head]; // Optional: clear reference for memory
    this.head++;

    if (this.head === this.tail) { // Optional: reset indices if queue becomes empty
        this.head = 0;
        this.tail = 0;
        this.elements = [];
    }
    return item;
  }

  peek() {
    if (this.head === this.tail) {
      return null;
    }
    return this.elements[this.head];
  }

  isEmpty() {
    return this.head === this.tail;
  }

  size() {
    return this.tail - this.head;
  }
}

