    if (this.head === this.tail) { // Optional: reset indices if queue becomes empty
        this.head = 0
        this.tail = 0
        this.elements = []
    }
    return item
  }

  peek() {
    if (this.head === this.tail) {
      return null
    }
    return this.elements[this.head]
  }

  isEmpty() {
    return this.head === this.tail
  }

  size() {
    return this.tail - this.head
  }
}

