const simpleMovingAverage = (data, windowSize) => {
  const averages = [];
  let sum = 0;
  let i = 0;

  if (windowSize <= 0 || !Array.isArray(data) || data.length === 0) {
    return [];
  }

  for (; i < windowSize - 1; i++) {
    if (i < data.length) {
      sum += data[i];
    } else {
      return []; // Not enough data for the first window;
    }
  }

  for (; i < data.length; i++) {
    sum += data[i];
    const average = sum / windowSize;
    averages.push(average);
    sum -= data[i - windowSize + 1];
  }

  return averages;
};

