const triangleAreaHeron = (a, b, c) => {
  const s = (a + b + c) / 2;
  const termA = s - a;
  const termB = s - b;
  const termC = s - c;

  if (s <= 0 || termA <= 0 || termB <= 0 || termC <= 0) {
    return 0; // Not a valid triangle, or degenerate; area is 0;
  }

  const product = s * termA * termB * termC;
  const area = Math.sqrt(product);
  return area;
};

