const isIsogram = (str) => {
  if (str === null || str === undefined) {
    return true;
  }

  const cleanedStr = str.toLowerCase();
  const seenChars = new Set();
  for (let i = 0; i < cleanedStr.length; i++) {
    const char = cleanedStr[i];
    if (char === ' ' || char === '-') {
      continue;
    }
    if (seenChars.has(char)) {
      return false;
    }
    seenChars.add(char);
  }
  return true;
};

