const hasConflict = (existingEvent, newEvent) => {
  const existingStart = new Date(`2000/01/01 ${existingEvent.start}`);
  const existingEnd = new Date(`2000/01/01 ${existingEvent.end}`);
  const newStart = new Date(`2000/01/01 ${newEvent.start}`);
  const newEnd = new Date(`2000/01/01 ${newEvent.end}`);

  const conflict1 = newStart < existingEnd && newStart >= existingStart;
  const conflict2 = newEnd > existingStart && newEnd <= existingEnd;
  const conflict3 = newStart <= existingStart && newEnd >= existingEnd;

  return conflict1 || conflict2 || conflict3;
};

