  let firstCharCode = letters[0].charCodeAt(0);
  let missingLetterCode = -1;

  for (let i = 1; i < letters.length; i++) {
    let currentCharCode = letters[i].charCodeAt(0);
    if (currentCharCode !== firstCharCode + i) {
      missingLetterCode = firstCharCode + i;
      break;
    }
  }

  if (missingLetterCode !== -1) {
    return String.fromCharCode(missingLetterCode);
  } else {
    // This case should ideally not be reached based on problem description
    // assuming exactly one letter is missing.
    return '';
  }
};

