function generateTimesTable(number, limit) {
  const result = [];
  let i = 1;

  while (i <= limit) {
    const product = number * i;
    const equation = `${number} * ${i} = ${product}`;
    result.push(equation);
    i++;
  }

  if (limit === 0) {
    return [];
  }

  return result;
}

