function longestCommonSuffix(strings) {
  if (strings.length === 0) {
    return "";
  }

  let commonSuffix = strings[0];
  let minLength = commonSuffix.length;

  for (let i = 1; i < strings.length; i++) {
    let currentString = strings[i];
    let currentLength = currentString.length;
    minLength = Math.min(minLength, currentLength);

    while (minLength > 0 && commonSuffix.slice(-minLength) !== currentString.slice(-minLength)) {
      minLength--;
    }

    if (minLength === 0) {
      return "";
    }
    commonSuffix = commonSuffix.slice(-minLength);
  }
  return commonSuffix;
}

