function isValidHexColor(hex) {
    if (typeof hex !== 'string') return false;

    hex = hex.toUpperCase(); 

    if (hex.length === 4) {
        if (hex[0] !== '#') return false; 
        for (let i = 1; i < 4; i++) {
            const char = hex[i];
            if (!((char >= '0' && char <= '9') || (char >= 'A' && char <= 'F'))) {
                return false; 
            }
        }
        return true;
    } else if (hex.length === 7) {
        if (hex[0] !== '#') return false;
        for (let i = 1; i < 7; i++) {
            const char = hex[i];
            if (!((char >= '0' && char <= '9') || (char >= 'A' && char <= 'F'))) {
                return false;
            }
        }
        return true;
    } else {
        return false;
    }
}

