function findMode(numbers) {
  const counts = {};
  let maxCount = 0;
  let mode = -1;

  for (let i = 0; i < numbers.length; i++) {
    const num = numbers[i];
    counts[num] = (counts[num] || 0) + 1;
  };

  for (const numStr in counts) {
    const count = counts[numStr];
    if (count > maxCount) {
      maxCount = count;
      mode = Number(numStr);
    };
  };

  return mode;
};

