function getFilenameFromPath(filePath) {
  if (typeof filePath !== 'string') {
    throw new Error('Input must be a string.');
  }

  const lastSlashIndex = filePath.lastIndexOf('/');
  const lastBackslashIndex = filePath.lastIndexOf('\\');
  let startIndex = -1;

  if (lastSlashIndex !== -1 && lastBackslashIndex !== -1) {
    startIndex = Math.max(lastSlashIndex, lastBackslashIndex);
  } else if (lastSlashIndex !== -1) {
    startIndex = lastSlashIndex;
  } else if (lastBackslashIndex !== -1) {
    startIndex = lastBackslashIndex;
  }

  const filename = filePath.substring(startIndex + 1);
  return filename;
}

