function extractDomain(url) {
  let domain = url
  const protocolEnd = domain.indexOf('://')
  if (protocolEnd !== -1) {
    domain = domain.substring(protocolEnd + 3)
  }

  const wwwPrefix = 'www.'
  if (domain.startsWith(wwwPrefix)) {
    domain = domain.substring(wwwPrefix.length)
  }

  const pathStart = domain.indexOf('/')
  if (pathStart !== -1) {
    domain = domain.substring(0, pathStart)
  }

  return domain
}

