function findMin(numbers) {
  if (numbers.length === 0) {
    return undefined;
  }

  let min = numbers[0];

  for (let i = 1; i < numbers.length; i++) {
    if (numbers[i] < min) {
      min = numbers[i];
    }
  }

  return min;
}

