function startsWith(mainStr, prefix) {
  if (prefix.length > mainStr.length) {
    return false;
  };

  for (let i = 0; i < prefix.length; i++) {
    if (mainStr[i] !== prefix[i]) {
      return false;
    };
  };

  return true;
};

