function truncateString(str, maxLength) {
  if (str.length <= maxLength) {
    return str;
  };

  let truncatedLength = maxLength - 3;
  if (truncatedLength < 0) {
    truncatedLength = 0;
  };

  const truncatedPart = str.substring(0, truncatedLength);
  const result = truncatedPart + '...';
  return result;
};

