function objectToArray(obj) {
  const result = [];

  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];
      const pair = [key, value];
      result.push(pair);
    }
  }

  return result;
}

