function arrayContains(arr, element) {
  let found = false;
  let i = 0;
  while (i < arr.length) {
    if (arr[i] === element) {
      found = true;
      break;
    }
    i++;
  }
  return found;
}

// Example usage:
let result1 = arrayContains([1, 2, 3], 2);
let result2 = arrayContains(['a', 'b'], 'c');
let result3 = arrayContains([10, 20, 30], 10);
let result4 = arrayContains([], 5);
let result5 = arrayContains([null, undefined], null);

