function endsWith(mainStr, suffix) {
  if (suffix.length > mainStr.length) {
    return false;
  }

  let mainStrEnd = mainStr.substring(mainStr.length - suffix.length);
  let isEqual = (mainStrEnd === suffix);

  return isEqual;
}

// Example usage:
let result1 = endsWith('hello world', 'world');
let result2 = endsWith('javascript', 'script');
let result3 = endsWith('apple', 'pie');
let result4 = endsWith('test', 'longer_suffix');
let result5 = endsWith('another example', 'example');

