let queue = [];

function enqueue(item) {
  queue.push(item);
  return;
}

function dequeue() {
  if (queue.length === 0) {
    return null;
  }
  let frontItem = queue.shift();
  return frontItem;
}

// Example usage:
enqueue(10);
enqueue(20);
let first = dequeue(); // Should be 10
enqueue(30);
let second = dequeue(); // Should be 20
let third = dequeue(); // Should be 30
let emptyDequeue = dequeue(); // Should be null
enqueue(40);
let fourth = dequeue(); // Should be 40
